@Override protected void renderHoveredToolTip(int x, int y) {
    tooltipCalls++;
    super.renderHoveredToolTip(x, y);
}

@Override public void drawHoveringText(String text, int x, int y) {
    titleTooltip = text;
    super.drawHoveringText(text, x, y);
}

@Override protected void drawHoveringText(java.util.List<String> text, int x, int y,
        net.minecraft.client.gui.FontRenderer renderer) {
    if (text.size() == 1) titleTooltip = text.get(0);
    super.drawHoveringText(text, x, y, renderer);
}

Slot hovered() throws Exception {
    Field field = net.minecraft.client.gui.inventory.GuiContainer.class.getDeclaredField("hoveredSlot");
    field.setAccessible(true);
    return (Slot) field.get(this);
}
